pub struct Cache<T> {
    value: T,
    hits: usize,
}

impl<T> Cache<T> {
    pub fn new(value: T) -> Self {
        Cache { value, hits: 0 }
    }

    pub fn get(&mut self) -> T {
        self.hits += 1;
        self.value.clone()
    }

    pub fn hits(&self) -> usize {
        self.hits
    }
}

pub fn run() -> (String, String, usize) {
    let mut c = Cache::new(String::from("config"));
    let a = c.get();
    let b = c.get();
    (a, b, c.hits())
}

